    if (this.canvas === canvas) { record(this, `arc:${this.fillStyle}`, x, y, r * 2, r * 2); addArc(this, x, y, r, r, 0, a0, a1, ccw); }
    return origArc.call(this, x, y, r, a0, a1, ccw);
