      const R = CFG.pathRadius - 1, [ti, tj] = g.at(to.x, to.y), [si, sj] = g.at(from.x, from.y);
      const k = Math.min(1, R / Math.max(Math.abs(ti - si), Math.abs(tj - sj), 1));
